  color: #2d3748;
}

a {
  color: #3182ce;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

footer {
  max-width: 640px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid #e2e8f0;
  color: #a0aec0;
  font-size: 0.875rem;
}

